import type { SsoHandoffTokenResponse } from "~/types/api-client";

type OAuthReturnTarget = {
  origin: string | null;
  platform: "web" | "native";
  /** App deep link supplied by the native SDK after local validation. */
  callbackUri: string | null;
  /** Native request correlation value generated by the SDK. */
  state: string | null;
};

function redirectToNative(callbackUri: string, params: Record<string, string>) {
  const callback = new URL(callbackUri);
  for (const [name, value] of Object.entries(params)) {
    callback.searchParams.set(name, value);
  }
  window.location.replace(callback.toString());
}

export function postAuthResult(
  target: OAuthReturnTarget,
  result: SsoHandoffTokenResponse,
) {
  if (target.platform === "native" && target.callbackUri && target.state) {
    redirectToNative(target.callbackUri, {
      handoffToken: result.handoffToken,
      expiresIn: String(result.expiresIn),
      expiresAt: result.expiresAt,
      state: target.state,
    });
    return;
  }

  if (target.origin && window.opener && !window.opener.closed) {
    window.opener.postMessage(
      {
        type: "AUTH_SUCCESS",
        payload: {
          ok: result.ok,
          handoffToken: result.handoffToken,
          expiresIn: result.expiresIn,
          expiresAt: result.expiresAt,
        },
      },
      target.origin,
    );
  }
  window.close();
}

export function postAuthClose(target: OAuthReturnTarget) {
  if (target.platform === "native" && target.callbackUri && target.state) {
    redirectToNative(target.callbackUri, {
      error: "access_denied",
      state: target.state,
    });
    return;
  }

  if (target.origin && window.opener && !window.opener.closed) {
    window.opener.postMessage({ type: "AUTH_CLOSE" }, target.origin);
  }
  window.close();
}
